		public static UIDifferences Create(GameObject go)
		{
			var ui = go.GetOrAddComponent<UIDifferences>();
			ui?.InitView();
			return ui;
		}

		/// <summary>
		/// 通过此方法获取的UGUI，在Dispose时不会释放GameObject，需要自行管理（一般在配合对象池机制时使用）。
		/// </summary>
		public static UIDifferences GetFromPool(GameObject go)
		{
			var ui = go.GetComponent<UIDifferences>();
			if (ui == null)
			{
				ui = Create(go);
			}

			ui.IsFromPool = true;
			return ui;
		}

		private bool _isInitView = false;

		protected override void InitView()
		{
			if (_isInitView)
			{
				return;
			}

			_isInitView = true;
